  fallback(){
    // No WebGL: draw a still, shaded 2D coin so the page never shows an empty box.
    const c = this.canvas, x = c.getContext('2d');
    this.ctx2d = x;
    this.render = (t) => {
      const W = c.width, H = c.height, cx = W/2, cy = H/2;
      x.fillStyle = '#0b0b0f'; x.fillRect(0,0,W,H);
      const ph = t*Math.PI*2;
      const sq = Math.abs(Math.cos(ph));                 // fake foreshortening
      const R = Math.min(W,H)*0.34;
      x.save(); x.translate(cx,cy); x.scale(Math.max(sq,0.06), 1);
      const g = x.createLinearGradient(-R, -R, R, R);
      const a = this.opts.albedo;
      const hex = (v)=>('0'+Math.round(Math.min(1,v)*255).toString(16)).slice(-2);
      const base = '#'+hex(a[0]*0.7)+hex(a[1]*0.7)+hex(a[2]*0.7);
      const lite = '#'+hex(a[0]*1.6)+hex(a[1]*1.6)+hex(a[2]*1.6);
      g.addColorStop(0, base); g.addColorStop(0.35+0.3*Math.sin(ph), lite); g.addColorStop(1, base);
      x.beginPath(); x.arc(0,0,R,0,Math.PI*2); x.fillStyle = g; x.fill();
      x.restore();
    };
    this.ok = true;
    this.render(0);
  }

  resize(){
    if(!this.gl) return;
    const gl = this.gl;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    const aspect = this.canvas.width / this.canvas.height;
    gl.uniformMatrix4fv(this.u.uProj, false, perspective(30*Math.PI/180, aspect, 0.1, 40));
  }

  // t in [0,1] -> exact, deterministic frame of the loop
  render(t){
    if(!this.gl) return;
    const gl = this.gl;
    const o = this.opts;
    const yaw   = (t * o.spins  + o.phase) * Math.PI * 2;
    const pitch = (t * o.flips  + o.phase * 0.5) * Math.PI * 2 + o.tilt;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    const aspect = this.canvas.width / this.canvas.height;
    gl.uniformMatrix4fv(this.u.uProj, false, perspective(30*Math.PI/180, aspect, 0.1, 40));
    gl.uniformMatrix3fv(this.u.uRot, false, rotMat(pitch, yaw));
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.drawElements(gl.TRIANGLES, COIN.count, gl.UNSIGNED_SHORT, 0);
  }
