/* =====================================================================
   PART 5 — Build the coins
   ===================================================================== */
const FRONT_MAP = buildFrontMap();

const METALS = {
  hero:   { albedo:[1.00,0.78,0.36], spec:[1.00,0.90,0.66], rough:0.30, gloss:110, relief:2.9 },
  bronze: { albedo:[0.86,0.50,0.26], spec:[1.00,0.76,0.52], rough:0.42, gloss:70,  relief:2.7 },
  silver: { albedo:[0.90,0.92,0.96], spec:[1.00,1.00,1.00], rough:0.26, gloss:130, relief:2.7 },
  gold:   { albedo:[1.00,0.76,0.30], spec:[1.00,0.89,0.60], rough:0.30, gloss:110, relief:2.7 },
  black:  { albedo:[0.16,0.15,0.20], spec:[0.72,0.70,0.92], rough:0.16, gloss:190, relief:3.2 }
};

const heroCanvas = document.getElementById('coin-hero');
const hero = new CoinRenderer(heroCanvas, Object.assign({}, METALS.hero, {
  frontMap: FRONT_MAP,
  backMap:  buildBackMap('10,000', 'REFERENCE STRIKE'),
  spins: 1, flips: 2, phase: 0, tilt: 0.10,
  bg: [0.043, 0.043, 0.055]
}));

const EDITIONS = [
  { key:'bronze', denom:'1,000',  sub:'BRONZE EDITION'   },
  { key:'silver', denom:'5,000',  sub:'SILVER EDITION'   },
  { key:'gold',   denom:'10,000', sub:'GOLD EDITION'     },
  { key:'black',  denom:'25,000', sub:'OBSIDIAN EDITION' }
];

const edRenderers = [];
EDITIONS.forEach((e, i) => {
  const tile = document.querySelector('.edition[data-edition="' + e.key + '"]');
  if(!tile) return;
  const cv = tile.querySelector('.edition-canvas');
  edRenderers.push(new CoinRenderer(cv, Object.assign({}, METALS[e.key], {
    frontMap: FRONT_MAP,
    backMap:  buildBackMap(e.denom, e.sub),
    spins: 1, flips: 2, phase: i * 0.17, tilt: 0.16,
    bg: [0.038, 0.038, 0.048]
  })));
});

/* =====================================================================
   PART 6 — Loop + programmatic API
   ===================================================================== */
const PERIOD = 9000; // ms per full loop
let rafId = null, running = true, t0 = 0, manual = null;

function frame(now){
  if(!running) return;
  if(!t0) t0 = now;
  const t = ((now - t0) / PERIOD) % 1;
  hero.render(t);
  for(const r of edRenderers) r.render(t);
  const sc = document.getElementById('scrub');
  if(sc && manual === null) sc.value = String(Math.round(t * 1000));
  rafId = requestAnimationFrame(frame);
}
function start(){
  if(running && rafId !== null) return;
  running = true; t0 = 0;
  rafId = requestAnimationFrame(frame);
}
function stop(){
  running = false;
  if(rafId !== null){ cancelAnimationFrame(rafId); rafId = null; }
}

window.demo = {
  canvas: heroCanvas,
  setTime(t){
    t = Number(t);
    if(!isFinite(t)) t = 0;
    t = ((t % 1) + 1) % 1;          // wrap into [0,1)
    hero.render(t);
    for(const r of edRenderers) r.render(t);
  },
  pause(){ stop(); },
  play(){ start(); }
};

start();

/* =====================================================================
   PART 7 — Page behaviour
   ===================================================================== */
// hero scrub control
const scrub = document.getElementById('scrub');
const scrubLabel = document.getElementById('scrub-label');
if(scrub){
  scrub.addEventListener('input', () => {
    manual = Number(scrub.value) / 1000;
    stop();
    window.demo.setTime(manual);
    scrubLabel.textContent = (manual * 360).toFixed(0) + '\u00B0';
  });
  scrub.addEventListener('change', () => {
    setTimeout(() => {
      manual = null;
      scrubLabel.textContent = 'Auto';
      start();
    }, 900);
  });
}

// cart
let cartCount = 0;
const cartEl = document.getElementById('cart-count');
const toastEl = document.getElementById('toast');
let toastTimer = null;
function toast(msg){
  toastEl.textContent = msg;
  toastEl.classList.add('on');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.classList.remove('on'), 2400);
}
document.querySelectorAll('button.buy').forEach(btn => {
  btn.addEventListener('click', () => {
    cartCount++;
    cartEl.textContent = String(cartCount);
    toast('Added \u2014 ' + btn.dataset.name + ' \u00B7 struck to order');
  });
});

// reveal on scroll
const io = new IntersectionObserver((entries) => {
  entries.forEach(en => { if(en.isIntersecting){ en.target.classList.add('in'); io.unobserve(en.target); } });
}, { threshold: 0.14 });
document.querySelectorAll('.rv').forEach(el => io.observe(el));

// ticker content (duplicated for a seamless marquee)
const tickItems = [
  'Die-struck at 240 tonnes', 'Edition of 1,000', '120-reed rolled collar',
  '<b>Gold \u2014 SOLD OUT</b>', 'Hand-antiqued relief', '44.5 mm \u00D7 3.4 mm',
  '<b>Obsidian \u2014 Winter 2026</b>', 'Numbered on the collar', 'Shipped in a velvet case',
  'No zinc pot metal', 'Dies defaced on sell-out'
];
const tick = document.getElementById('tick');
tick.innerHTML = (tickItems.map(s => '<span>' + s + '</span>').join('') ).repeat(2);

// keep rendering crisp if the page is resized (buffer size is fixed, so just re-render)
window.addEventListener('resize', () => {
  if(!running) return;
  hero.resize();
  for(const r of edRenderers) r.resize();
});

// pause the loop when the tab is hidden; resume when visible
document.addEventListener('visibilitychange', () => {
  if(document.hidden) stop();
  else if(manual === null) start();
});
</script>
